/ ((n-1) * (n-2) * (n-3) * s**4)) - (3 * (n-1)**2) / ((n-2) * (n-3))\n\nprint(f\"\\nn = {n}\")\nprint(f\"Mean = {mean}\")\nprint(f\"Sample variance (s^2) = {s2}\")\nprint(f\"Sum of 4th moments = {sum_4th}\")\nprint(f\"s^4 = {s**4}\")\nprint(f\"\\nUnbiased sample Fisher excess Kurtosis: {g2}\")\nprint(f\"Rounded to 3 decimal places: {round(g2, 3)}\")\n\n# Let's also verify using a simpler form\n# The bias-corrected kurtosis can be computed as:\n# g2 = ((n+1)*n/(n-1)) * m4/s^4 - 3\n\n# Wait, there's simpler check - let's try with R's approach\n# R uses: (n*(n+1)/(n-1)*(n-2)*(n-3)) * sum((x-mean)^4)/s^4 - 3*(n-1)^2/((n-2)*(n-3))\n\n# This is exactly what I calculated above.\n# However, I realize the issue - let's verify with actual values more carefully\n\n# Another common formula: \n# g2 = ((n+1)*n)/(n-1)*(m4/s^4) - 3\n\n# Let's double-check by calculating both biased and unbiased:\nbiased_kurtosis = m4 = sum((x - mean)**4 for x in data) / n\nbiased_excess = (sum((x - mean)**4 for x in data) / n) / (s2**2) - 3\n\nprint(f\"\\nBiased excess kurtosis (using n): {biased_excess}\")\n\n# Correct formula for unbiased sample excess kurtosis:\n# The standard textbook formula is:\n# g2 = [(n+1)*n*m4 / ((n-1)*(n-2)*(n-3)*s^4)] - 3*(n-1)^2 / ((n-2)*(n-3))\n# where m4 = sum((x-mean)^4)/n (population 4th moment) and s^4 uses (n-1)\n\n# Using the formula directly from scipy documentation\n# From scipy.stats import kurtosis\n# The formula used is: \n# kurtosis = (n+1)*n*m4/((n-1)*(n-2)*(n-3)*s^4) - 3*(n-1)^2/((n-2)*(n-3))\n# where m4 uses population formula (n), and s^4 uses (n-1)\n\nm2_pop = sum((x - mean)**2 for x in data) / n\nm4_pop = sum((x - mean)**4 for x in data) / n\n\ng2_final = ((n+1) * n * m4_pop / ((n-1) * (n-2) * (n-3) * (m2_pop**2))) - (3 * (n-1)**2) / ((n-2) * (n-3))\n\nprint(f\"\\nUsing population moments (m2_pop, m4_pop) formula:\")\nprint(f\"Unbiased sample Fisher excess Kurtosis: {g2_final}\")\nprint(f\"Rounded: {round(g2_final, 3)}\")\n\n# This should match scipy