\nprint(f\"Term 2 = 3*(n-1)^2 / ((n-2)*(n-3)) = {term2}\")\nprint(f\"\\nUnbiased sample Fisher excess Kurtosis = {g2}\")\nprint(f\"Rounded to 3 decimal places = {round(g2, 3)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
