or 1945 and 1948):\")\nfor year, val in zip(range(1941, 1951), data_1948bull):\n    print(f\"FY {year}: {val}\")\n\n# Quick function to compute unbiased excess kurtosis\ndef compute_kurtosis(arr):\n    n = len(arr)\n    mean = sum(arr) / n\n    m2 = sum((x - mean)**2 for x in arr) / n\n    m4 = sum((x - mean)**4 for x in arr) / n\n    g2 = ((n+1) * n * m4 / ((n-1) * (n-2) * (n-3) * (m2**2))) - (3 * (n-1)**2) / ((n-2) * (n-3))\n    return g2\n\nprint(f\"\\nWith 1950 bulletin data: {round(compute_kurtosis(data), 3)}\")\nprint(f\"With 1948 bulletin for 1945,1948: {round(compute_kurtosis(data_1948bull), 3)}\")\n\n# Since the question asks about nominal amount from FY 1941 to FY 1950,\n# and we want the most accurate data, we should use the most recent \n# revised values from the 1950 bulletin for overlapping years.\n# The answer should be -3.846\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
